    management_no, achievement_type, teacher_user_id, organization_code, evaluation_year,
    management_item_code, achievement_date, achievement_name, attachment_ref,
    achievement_status, deleted_yn, created_by, updated_by
) VALUES (
    #{managementNo}, 'EMPLOYMENT_RATE_ACHIEVEMENT', #{teacherUserId}, #{organizationCode}, #{evaluationYear},
    #{managementItemCode}, CAST(#{achievementDate} AS date), #{achievementName}, #{attachmentRef},
    'DRAFT', 'N', #{updatedBy}, #{updatedBy}
)

